   if(n.equals("2: ectoplasmic boon"))return o.put("compiled",true).put("mechanic","osybus_ectoplasmic_boon").put("emanation_ft",15).put("save_ability","str").put("save_dc",15).put("manual_roll_required",true).put("failure_speed_reduction_ft",10).put("failure_duration","until start of target next turn");
