   if(n.equals("possessive aura"))return o.put("compiled",true).put("mechanic","possessive_aura").put("emanation_ft",5).put("trigger","creature_ends_turn_in_aura").put("save_ability","cha").put("save_dc",14).put("manual_roll_required",true).put("failure_condition","charmed").put("charmed_speed",0).put("repeat_save","end_of_each_target_turn").put("automatic_success_after_minutes",1);
   if(n.startsWith("legendary resistance")){int uses=n.contains("4/day")?4:n.contains("3/day")?3:n.contains("2/day")?2:n.contains("1/day")?1:0;int domainBonus=n.contains("or 5/day")?5:n.contains("or 4/day")?4:n.contains("or 3/day")?3:uses;return o.put("compiled",true).put("mechanic","legendary_resistance").put("uses_base",uses).put("uses_in_domain_or_lair",domainBonus).put("trigger","failed_saving_throw").put("effect","choose_success_instead").put("resource_spend_explicit",true);}
